import{_ as n,l as i,o as e,c as l,v as o,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"弱引用与终结器","description":"","frontmatter":{"title":"弱引用与终结器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/weak-refs-finalizers.md","filePath":"cs/weak-refs-finalizers.md","lastUpdated":1789023840000}'),h={name:"cs/weak-refs-finalizers.md"};function B(f,a,m,_,u,E){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="弱引用与终结器" tabindex="-1">弱引用与终结器 <a class="header-anchor" href="#弱引用与终结器" aria-label="Permalink to &quot;弱引用与终结器&quot;">​</a></h1><div class="epigraph"><p>弱引用不阻止回收；回收后队列通知缓存失效。终结器在对象不可达后跑用户代码，次序与及时性几乎无法保证，容易复活与死锁。</p><footer>—— 据 Java Reference 与 Finalizer 规范；Jones 手册；Boehm 对终结器的警告整理</footer></div><p>上一课<a href="/cs/bump-allocation-tlab">TLAB</a> 把对象生出来。缺口是<strong>非强可达</strong>：Weak/Soft/Phantom、终结器。语言特性落地课序下一课从闭包转换开始；本课收束内存管理。主干 GC 未细讲弱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存：希望条目随对象死。弱引用：GC 发现只有弱到达则可清并把引用入队。终结器：<code>finalize</code> 在回收前调用，对象可复活（再被强引用）。缺口是<strong>可达性等级</strong>，不是 bump。</p><p>现代语言倾向 <code>Cleaner</code>/显式 <code>Drop</code>，弱化终结器。</p><h3 id="弱不是-option-的-none" tabindex="-1">弱不是 Option 的 None <a class="header-anchor" href="#弱不是-option-的-none" aria-label="Permalink to &quot;弱不是 Option 的 None&quot;">​</a></h3><p>Option 是静态可能空；弱引用是动态被 GC 清空。可组合：<code>Option&lt;Weak&lt;T&gt;&gt;</code>。</p><p><span class="marginnote">Java 的 java.lang.ref。Boehm, Destructors, Finalizers, and Synchronization。Rust 无终结器，有 Drop。Jones 手册。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>GC 标记分阶段：强扫描后再处理弱。若对象未强达，清弱指针、入 ReferenceQueue。终结器：入终队列，单独线程跑，跑完再回收（或复活）。</p>',11)),(e(),s(c,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E5%BC%BA%E5%8F%AF%E8%BE%BE%22%5D%20--%3E%20LIVE%5B%22%E6%B4%BB%22%5D%0A%20%20WEAK%5B%22%E4%BB%85%E5%BC%B1%22%5D%20--%3E%20CLR%5B%22%E6%B8%85%E7%A9%BA%E5%B9%B6%E5%85%A5%E9%98%9F%22%5D%0A%20%20FIN%5B%22%E6%9C%89%E7%BB%88%E7%BB%93%E5%99%A8%22%5D%20--%3E%20Q%5B%22%E7%BB%88%E7%BB%93%E5%99%A8%E7%BA%BF%E7%A8%8B%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与分代：弱引用处理在 minor/full 的时机不同，实现复杂。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>终结器线程持锁+分配可死锁、可饿死。及时性：内存压力大才跑。不要用终结器关文件；用显式作用域。弱哈希表要处理清队列。</p><p>安全：终结器里看的对象字段可能半构造——语言规则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写所有引用类型。后课默认：弱引用服务缓存；终结器尽量不用。下一课闭包转换：从堆对象到函数表示。</p><p>也不把弱当密码学弱密钥。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>弱引用不保持对象；队列做通知。</li><li>终结器不可靠、可复活，应用层应显式释放。</li><li>GC 须分阶段处理引用强度。</li><li>出处：Java Reference API；Boehm；Jones 手册。</li></ul>',9))])}const T=n(h,[["render",B]]);export{b as __pageData,T as default};
